<script>
(function(){var api='api/repo_api.php';function esc(v){return $('<div>').text(v==null?'':v).html();}function money(v){return Number(v||0).toFixed(2);}function iso(d){return d.toISOString().slice(0,10);}function render(rows){if(!rows.length){$('#summary').hide();return '<div class="alert alert-warning">No recorded returns.</div>';}var qty=0,amount=0,h='<div class="panel panel-default"><div class="return-panel-title">User Items Returns</div><div class="panel-body"><table id="returns-table" class="table table-striped table-bordered return-table" width="100%"><thead><tr><th>Return ID</th><th>Sale ID</th><th>Item</th><th>Category</th><th>Shift</th><th>Quantity</th><th>Amount</th><th>Status</th><th>Confirmed By</th></tr></thead><tbody>';rows.forEach(function(r){qty+=Number(r.qty||0);amount+=Number(r.amount||0);var state=String(r.status||'Processing').toLowerCase();h+='<tr><td>'+r.id+'</td><td>'+r.sale_id+'</td><td>'+esc(r.item_name)+'</td><td>'+esc(r.category_name)+'</td><td>'+esc(r.shift)+'</td><td>'+r.qty+'</td><td>'+money(r.amount)+'</td><td><span class="return-status '+state+'">'+esc(r.status)+'</span></td><td>'+esc(r.confirmed_by||'—')+'</td></tr>';});$('#return-lines').text(rows.length);$('#return-qty').text(qty);$('#return-amount').text(money(amount));$('#summary').show();return h+'</tbody></table></div></div>';}function load(){var user=$('#user').val(),from=$('#from').val(),to=$('#to').val();if(!user||!from||!to){$('#result').html('<div class="alert alert-warning">Select a user and both dates.</div>');return;}$('#result').html('<div class="alert alert-info">Loading returns...</div>');$.getJSON(api,{action:'user_returns',user_id:user,from:from,to:to}).done(function(r){if(!r.ok){$('#result').html('<div class="alert alert-danger">'+esc(r.message)+'</div>');return;}var rows=r.data.rows||[];$('#result').html(render(rows));if(rows.length)$('#returns-table').DataTable({responsive:true,pageLength:25,order:[[4,'desc'],[0,'desc']]});}).fail(function(){$('#result').html('<div class="alert alert-danger">Could not load user returns.</div>');});}$('.quick-date').on('click',function(){var now=new Date(),start=new Date(now),range=$(this).data('range');if(range==='yesterday'){start.setDate(now.getDate()-1);now=new Date(start);}else if(range==='week'){start.setDate(now.getDate()-now.getDay());}else if(range==='month'){start=new Date(now.getFullYear(),now.getMonth(),1);}$('#from').val(iso(start));$('#to').val(iso(now));load();});$('#custom-date').on('click',function(){$('#custom-range').slideToggle(150);});$('#search').on('click',load);$(document).ready(function(){App.init();if($.fn.select2){if($('#user').hasClass('select2-hidden-accessible'))$('#user').select2('destroy');$('#user').select2({width:'100%',minimumResultsForSearch:0});}});})();
</script>
